class Counter {
    int value;
    Counter(int value) {
        this.value = value;
    }
    void moveTo(Counter other, int amount) {
        this.value = this.value - amount;
        other.value = other.value + amount;
    }
}
public class Main {
    public static void main(String[] args) {
        Counter a = new Counter(10);
        Counter b = new Counter(5);
        a.moveTo(b, 3);
        System.out.println(a.value);
    }
}

